import json
with open('/app/resources/treasury_bulletin_1940_03.json', 'r') as f:
    data = json.load(f)

doc = data['document']

# Search for exchange rate or dollar/pound related content
def search_nested(obj, target, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search_nested(v, target, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_nested(item, target, f'{path}[{i}]')
    elif isinstance(obj, str):
        if target.lower() in obj.lower():
            print(f'Found at {path}: {obj[:200]}')

search_nested(data, 'dollar')
